{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "Although the current ACL is private, the bucket has no account-level resource control preventing a future ACL or bucket policy from exposing it publicly."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket is not encrypted with KMS by default",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly enforce KMS-backed default encryption, reducing control and auditability over encryption key usage."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "Without versioning, accidental deletion or malicious overwriting of objects cannot be readily reversed."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is disabled",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The bucket does not record server access requests, limiting investigation and detection of unauthorized or suspicious access."
    }
  ],
  "patched_code": "variable "s3_access_log_bucket_name" {
  description = "Name of an existing, access-log-enabled destination bucket in the same AWS account and Region. The bucket must permit S3 log delivery."
  type        = string

  validation {
    condition     = var.s3_access_log_bucket_name != "my-tf-test-bucket-ggff"
    error_message = "The access log destination must be different from the source bucket."
  }
}

resource "aws_s3_bucket" "b" {
  bucket = "my-tf-test-bucket-ggff"
  acl    = "private"
}

resource "aws_s3_bucket_public_access_block" "b" {
  bucket = aws_s3_bucket.b.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "b" {
  bucket = aws_s3_bucket.b.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "b" {
  bucket = aws_s3_bucket.b.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "b" {
  bucket        = aws_s3_bucket.b.id
  target_bucket = var.s3_access_log_bucket_name
  target_prefix = "s3-access-logs/${aws_s3_bucket.b.id}/"
}
",
  "fix_summary": "Added a complete S3 Public Access Block, KMS-backed default encryption, versioning, and server access logging. Logging uses a required existing destination bucket and prevents configuration of the source bucket as its own log destination."
}
